-- California. The state had thirty-one stops, nearly all gravity hills and
-- Bigfoot statues from the original scan, and it is the largest single gap the
-- index has had.
--
-- Six dropped. Four were found by position rather than slug: Ballarat is held
-- under the plain town name, and the Willow Creek museum sits 83 metres from
-- its own earlier entry under a slightly different name.
--
-- Two are the apostrophe, held as world-s-tallest — the thermometer at Baker
-- and the redwood chainsaw carving. Ninth and tenth time that has hidden a
-- duplicate.
--
-- Three renamed. The Santa Cruz Mystery Spot is the original, the one every
-- other tilted room in this index is a copy of, and it still does not get the
-- plain slug because Onsted, Michigan got there first. Renaming a live page to
-- correct that would break every link to it, which is a worse outcome than an
-- unfair slug.
--
-- Well sourced: nps.gov, parks.ca.gov and fs.usda.gov are the top three.
--
-- Seven proximity flags kept, all real. Trees of Mystery has its Paul Bunyan
-- in the car park; Calico has a mystery shack at the ghost town gate; Fisherman's
-- Wharf puts a submarine 71 metres from an arcade of antique machines.
--
-- 216 stops, every one with a source.

insert into public.stops
  (name, slug, category, latitude, longitude, city, state, description,
   public_access, source, website, timezone, verified_at)
values
  ('Patterson-Gimlin Film Site at Bluff Creek', 'patterson-gimlin-film-site-at-bluff-creek', 'cryptids', 41.4402, -123.70192, 'Orleans', 'CA', 'This remote Bluff Creek location is the reconstructed site of the 1967 Patterson-Gimlin film. Forest roads are rough and seasonal, so the pin is for prepared backcountry visitors rather than casual roadside traffic.', 'limited', 'https://www.bluffcreekproject.com/', null, 'America/Los_Angeles', now()),
  ('Happy Camp Bigfoot Statue', 'happy-camp-bigfoot-statue', 'cryptids', 41.79892, -123.37473, 'Happy Camp', 'CA', 'Happy Camp''s large roadside Bigfoot figure marks the community''s long-running embrace of Sasquatch folklore along the Bigfoot Scenic Byway.', 'roadside', 'https://www.visitsiskiyou.org/', null, 'America/Los_Angeles', now()),
  ('Legend of Bigfoot', 'legend-of-bigfoot', 'cryptids', 40.03429, -123.7931, 'Garberville', 'CA', 'This redwood-country roadside shop surrounds visitors with carved Bigfoot figures, local souvenirs and the visual culture that grew around Northern California Sasquatch lore.', 'limited', 'https://www.roadsideamerica.com/tip/16055', null, 'America/Los_Angeles', now()),
  ('Trees of Mystery', 'trees-of-mystery', 'roadside-oddities', 41.58479, -124.08588, 'Klamath', 'CA', 'A classic redwood attraction combining giant trees, unusual forest displays, a canopy gondola and decades of roadside mythology on U.S. 101.', 'limited', 'https://treesofmystery.net/', null, 'America/Los_Angeles', now()),
  ('Paul Bunyan and Babe the Blue Ox', 'paul-bunyan-babe-trees-of-mystery', 'roadside-oddities', 41.58446, -124.08618, 'Klamath', 'CA', 'The enormous Paul Bunyan and Babe statues have greeted travelers outside Trees of Mystery since the mid-twentieth century and remain one of the North Coast''s signature roadside photo stops.', 'open', 'https://treesofmystery.net/', null, 'America/Los_Angeles', now()),
  ('Confusion Hill Gravity House', 'confusion-hill-gravity-house', 'roadside-oddities', 39.91893, -123.76494, 'Piercy', 'CA', 'Confusion Hill''s tilted Gravity House uses perspective and slope to create apparent violations of gravity, continuing a roadside attraction that opened in 1949.', 'limited', 'https://www.confusionhill.com/', null, 'America/Los_Angeles', now()),
  ('Chandelier Drive-Thru Tree', 'chandelier-drive-thru-tree', 'roadside-oddities', 39.85874, -123.71929, 'Leggett', 'CA', 'A living coast redwood has a vehicle-sized tunnel cut through its trunk, allowing ordinary cars to drive through one of California''s surviving classic tree attractions.', 'limited', 'http://www.drivethrutree.com/', null, 'America/Los_Angeles', now()),
  ('Shrine Drive-Thru Tree', 'shrine-drive-thru-tree', 'roadside-oddities', 40.2682, -123.87499, 'Myers Flat', 'CA', 'This living redwood contains a narrow automobile passage and sits among other old-school roadside attractions along the Avenue of the Giants.', 'limited', 'https://www.visitredwoods.com/listing/shrine-drive-thru-tree/560/', null, 'America/Los_Angeles', now()),
  ('Tour-Thru Tree', 'tour-thru-tree', 'roadside-oddities', 41.52202, -124.03053, 'Klamath', 'CA', 'A privately operated redwood with a vehicle tunnel offers another surviving example of the once-common drive-through-tree era of California tourism.', 'limited', 'https://www.tourthrutree.com/', null, 'America/Los_Angeles', now()),
  ('World Famous Tree House', 'world-famous-tree-house', 'roadside-oddities', 39.88142, -123.75264, 'Piercy', 'CA', 'Rooms carved into the base of a giant redwood create a tiny walk-in tree dwelling. The long-running Highway 101 attraction reopened to visitors in 2025.', 'limited', 'https://www.roadsideamerica.com/tip/13769', null, 'America/Los_Angeles', now()),
  ('One Log House', 'one-log-house', 'roadside-oddities', 40.00979, -123.79009, 'Garberville', 'CA', 'A single enormous redwood log was hollowed into a compact mobile home, exhibited around the country and eventually parked permanently beside U.S. 101.', 'limited', 'https://oneloghouse.com/', null, 'America/Los_Angeles', now()),
  ('Grandfather Tree', 'grandfather-tree', 'roadside-oddities', 40.01337, -123.79137, 'Piercy', 'CA', 'A huge old-growth redwood anchors a traditional roadside stop where travelers can stand beside one of the North Coast''s most photographed surviving giants.', 'limited', 'https://www.visitredwoods.com/', null, 'America/Los_Angeles', now()),
  ('Eternal Tree House', 'eternal-tree-house', 'roadside-oddities', 40.40108, -123.95021, 'Redcrest', 'CA', 'A room was carved into the burned-out base of an ancient redwood, turning a living-tree remnant into a tiny roadside chamber beside the Avenue of the Giants.', 'limited', 'https://redcrestresort.com/', null, 'America/Los_Angeles', now()),
  ('Immortal Tree', 'immortal-tree', 'roadside-oddities', 40.41693, -123.96753, 'Redcrest', 'CA', 'This roughly thousand-year-old redwood survived lightning, fire, flood and an attempted logging cut, with scars and high-water marks still visible from the roadside stop.', 'roadside', 'https://discoversouthernhumboldt.com/', null, 'America/Los_Angeles', now()),
  ('Carson Mansion', 'carson-mansion', 'roadside-oddities', 40.80562, -124.15848, 'Eureka', 'CA', 'One of America''s most elaborate Queen Anne houses rises over Eureka''s waterfront. It is now a private club, so OddWay should treat it strictly as an exterior-view stop.', 'roadside', 'https://www.visitredwoods.com/listing/carson-mansion/442/', null, 'America/Los_Angeles', now()),
  ('Blue Ox Millworks & Historic Park', 'blue-ox-millworks-historic-park', 'museums', 40.80773, -124.14673, 'Eureka', 'CA', 'A working Victorian-era-style mill preserves antique woodworking machinery, blacksmithing, printing and traditional craft techniques rather than displaying them only behind glass.', 'limited', 'https://www.blueoxmill.com/', null, 'America/Los_Angeles', now()),
  ('Ferndale Cemetery', 'ferndale-cemetery', 'weird-history', 40.57338, -124.2619, 'Ferndale', 'CA', 'The steep hillside cemetery climbs above Ferndale in dense rows of old markers, creating one of California''s most visually dramatic historic burial grounds. Visit respectfully during lawful access.', 'limited', 'https://www.visitferndale.com/', null, 'America/Los_Angeles', now()),
  ('Shasta State Historic Park', 'shasta-state-historic-park', 'weird-history', 40.59626, -122.49501, 'Shasta', 'CA', 'Brick ruins, a preserved courthouse and traces of a Gold Rush business district survive in what was once the major mining-era town of Shasta.', 'open', 'https://www.parks.ca.gov/?page_id=456', null, 'America/Los_Angeles', now()),
  ('Lake Shasta Caverns', 'lake-shasta-caverns', 'roadside-oddities', 40.80443, -122.30431, 'Lakehead', 'CA', 'A boat ride, bus climb and guided underground tour lead to large limestone chambers high above Shasta Lake.', 'limited', 'https://www.lakeshastacaverns.com/', null, 'America/Los_Angeles', now()),
  ('Pluto''s Cave', 'plutos-cave', 'roadside-oddities', 41.56844, -122.28333, 'Weed', 'CA', 'A large lava tube formed by eruptions from the Mount Shasta region can be entered from public forest land; rough footing and darkness require proper equipment.', 'limited', 'https://www.fs.usda.gov/r05/klamath/recreation', null, 'America/Los_Angeles', now()),
  ('Mount Shasta City Park Headwaters', 'mount-shasta-city-park-headwaters', 'folklore', 41.32694, -122.32389, 'Mount Shasta', 'CA', 'Spring water emerging at the Sacramento River headwaters has accumulated spiritual and New Age significance around Mount Shasta, alongside the site''s ordinary public-park use.', 'open', 'https://www.msrec.org/mount-shasta-city-park', null, 'America/Los_Angeles', now()),
  ('Bunny Flat Trailhead', 'bunny-flat-trailhead', 'folklore', 41.35373, -122.23359, 'Mount Shasta', 'CA', 'This high-elevation trailhead is a practical public gateway to Mount Shasta, a mountain surrounded by Lemurian, UFO and mystical folklore as well as serious mountaineering history.', 'limited', 'https://www.fs.usda.gov/r05/shasta-trinity/recreation', null, 'America/Los_Angeles', now()),
  ('Subway Cave Lava Tube', 'subway-cave-lava-tube', 'roadside-oddities', 40.68601, -121.41885, 'Old Station', 'CA', 'A self-guided path descends into a dark lava tube formed by Hat Creek volcanic flows, with no artificial lighting inside.', 'limited', 'https://www.fs.usda.gov/r05/lassen/recreation', null, 'America/Los_Angeles', now()),
  ('Skull Cave', 'skull-cave', 'roadside-oddities', 41.73138, -121.51066, 'Tulelake', 'CA', 'One of Lava Beds National Monument''s largest lava-tube entrances descends toward an ice floor; seasonal bat and cave closures must be respected.', 'limited', 'https://www.nps.gov/labe/', null, 'America/Los_Angeles', now()),
  ('Catacombs Cave', 'catacombs-cave', 'roadside-oddities', 41.70504, -121.51531, 'Tulelake', 'CA', 'A long, branching lava-tube system offers a more technical caving experience than the monument''s easy caves and requires route-finding, lights and current closure checks.', 'limited', 'https://www.nps.gov/labe/', null, 'America/Los_Angeles', now()),
  ('Captain Jack''s Stronghold', 'captain-jacks-stronghold', 'weird-history', 41.81389, -121.39639, 'Tulelake', 'CA', 'A loop trail crosses the lava landscape used by Kintpuash and Modoc defenders during the 1872–73 Modoc War. The site should be approached as a serious Indigenous and military-history landscape.', 'open', 'https://www.nps.gov/labe/', null, 'America/Los_Angeles', now()),
  ('Petroglyph Point', 'petroglyph-point', 'weird-history', 41.87125, -121.36446, 'Tulelake', 'CA', 'A cliff face holds one of the largest concentrations of Native rock imagery in California. Visitors should remain on designated paths and treat the carvings as protected cultural heritage, not a novelty.', 'limited', 'https://www.nps.gov/labe/', null, 'America/Los_Angeles', now()),
  ('Sulphur Works', 'sulphur-works', 'roadside-oddities', 40.43772, -121.53582, 'Mineral', 'CA', 'Steam vents, boiling mud and sulfurous ground sit immediately beside Lassen''s park road, exposing the still-active hydrothermal system beneath the volcano.', 'limited', 'https://www.nps.gov/lavo/', null, 'America/Los_Angeles', now()),
  ('Bumpass Hell', 'bumpass-hell', 'roadside-oddities', 40.45764, -121.50472, 'Mineral', 'CA', 'A boardwalk enters Lassen''s largest hydrothermal basin, where boiling pools, steam vents and acidic ground create an unusually hostile-looking landscape.', 'limited', 'https://www.nps.gov/lavo/', null, 'America/Los_Angeles', now()),
  ('Cinder Cone & Painted Dunes', 'cinder-cone-painted-dunes', 'roadside-oddities', 40.55035, -121.3171, 'Old Station', 'CA', 'A steep trail climbs a young cinder cone above multicolored volcanic dunes and the Fantastic Lava Beds in Lassen''s remote northeast corner.', 'limited', 'https://www.nps.gov/lavo/', null, 'America/Los_Angeles', now()),
  ('Devastated Area Interpretive Trail', 'devastated-area-interpretive-trail', 'roadside-oddities', 40.53944, -121.57642, 'Mineral', 'CA', 'A short loop crosses terrain transformed by Lassen Peak''s 1915 eruption, with enormous volcanic rocks and interpretive evidence of the blast.', 'limited', 'https://www.nps.gov/lavo/', null, 'America/Los_Angeles', now()),
  ('Boiling Springs Lake', 'boiling-springs-lake', 'roadside-oddities', 40.43833, -121.39728, 'Mineral', 'CA', 'One of the largest hot-water lakes in the United States sits in Lassen''s Warner Valley, surrounded by steaming ground and hydrothermal features.', 'limited', 'https://www.nps.gov/lavo/', null, 'America/Los_Angeles', now()),
  ('Devil''s Kitchen', 'devils-kitchen', 'roadside-oddities', 40.44578, -121.40702, 'Mineral', 'CA', 'Fumaroles, mudpots and steaming acidic ground fill this backcountry hydrothermal area reached by trail from Warner Valley.', 'limited', 'https://www.nps.gov/lavo/', null, 'America/Los_Angeles', now()),
  ('Black Chasm Cavern', 'black-chasm-cavern', 'roadside-oddities', 38.43245, -120.62633, 'Volcano', 'CA', 'Guided tours descend into a National Natural Landmark known for dense displays of delicate helictite crystals that twist in seemingly impossible directions.', 'limited', 'https://caverntours.com/black-chasm-cavern/', null, 'America/Los_Angeles', now()),
  ('Moaning Caverns', 'moaning-caverns', 'roadside-oddities', 38.06904, -120.46604, 'Vallecito', 'CA', 'A huge vertical chamber produces the low resonance that gave the cave its name, with guided stair tours and more adventurous underground options.', 'limited', 'https://moaningcaverns.com/', null, 'America/Los_Angeles', now()),
  ('Mercer Caverns', 'mercer-caverns', 'roadside-oddities', 38.15117, -120.47809, 'Murphys', 'CA', 'Discovered during the Gold Rush era, the show cave descends through multiple limestone chambers filled with stalactites, flowstone and other formations.', 'limited', 'https://mercercaverns.net/', null, 'America/Los_Angeles', now()),
  ('Malakoff Diggins State Historic Park', 'malakoff-diggins-state-historic-park', 'weird-history', 39.37378, -120.91467, 'North Bloomfield', 'CA', 'Hydraulic miners effectively washed away a mountain here, leaving immense man-made cliffs and a landscape central to one of America''s first major environmental lawsuits.', 'limited', 'https://www.parks.ca.gov/?page_id=494', null, 'America/Los_Angeles', now()),
  ('Empire Mine State Historic Park', 'empire-mine-state-historic-park', 'weird-history', 39.20705, -121.04708, 'Grass Valley', 'CA', 'Surface buildings, gardens and an underground mine model interpret one of California''s oldest, deepest and most productive hard-rock gold mines.', 'open', 'https://www.parks.ca.gov/?page_id=499', null, 'America/Los_Angeles', now()),
  ('Kennedy Gold Mine', 'kennedy-gold-mine', 'weird-history', 38.36686, -120.78021, 'Jackson', 'CA', 'Towering headframes, tailing wheels and preserved surface works remain from a mine that reached more than a mile below ground.', 'limited', 'https://kennedygoldmine.com/', null, 'America/Los_Angeles', now()),
  ('Preston Castle', 'preston-castle', 'weird-history', 38.36111, -120.93583, 'Ione', 'CA', 'The Romanesque former Preston School of Industry juvenile institution now opens for scheduled history tours, events and selected paranormal programs.', 'limited', 'https://prestoncastle.org/', null, 'America/Los_Angeles', now()),
  ('Old Sacramento Underground Tours', 'old-sacramento-underground-tours', 'weird-history', 38.5848, -121.50496, 'Sacramento', 'CA', 'Guided tours enter spaces left beneath Sacramento after streets and buildings were raised during the nineteenth century to escape repeated flooding.', 'limited', 'https://www.oldsacramento.com/business_directory/underground-tours/', null, 'America/Los_Angeles', now()),
  ('Delta King', 'delta-king', 'weird-history', 38.58278, -121.50694, 'Sacramento', 'CA', 'A 1920s sternwheel riverboat is permanently moored on the Sacramento waterfront and now operates as a hotel, restaurant and theater.', 'open', 'https://www.deltaking.com/', null, 'America/Los_Angeles', now()),
  ('Sacramento Historic City Cemetery', 'sacramento-historic-city-cemetery', 'weird-history', 38.56368, -121.50073, 'Sacramento', 'CA', 'The city''s oldest municipal cemetery preserves elaborate nineteenth-century monuments, pioneer graves and garden-style burial plots. Visit respectfully during posted hours.', 'limited', 'https://www.cityofsacramento.gov/public-works/cemeteries', null, 'America/Los_Angeles', now()),
  ('Columbia State Historic Park', 'columbia-state-historic-park', 'museums', 38.03581, -120.401, 'Columbia', 'CA', 'A remarkably intact Gold Rush business district survives as a state park with historic storefronts, stagecoaches and period demonstrations.', 'open', 'https://www.parks.ca.gov/?page_id=552', null, 'America/Los_Angeles', now()),
  ('Railtown 1897 State Historic Park', 'railtown-1897-state-historic-park', 'weird-history', 37.94981, -120.41617, 'Jamestown', 'CA', 'Historic steam locomotives, a working roundhouse and railroad shops preserve the Sierra Railway complex used in countless film and television productions.', 'limited', 'https://www.parks.ca.gov/?page_id=491', null, 'America/Los_Angeles', now()),
  ('Chinese Camp Ghost Town', 'chinese-camp-ghost-town', 'weird-history', 37.86914, -120.44276, 'Chinese Camp', 'CA', 'A once-busy Gold Rush settlement retains aging brick and wooden structures along a quiet highway corridor; explore only from public roads and lawful areas.', 'roadside', 'https://www.visittuolumne.com/', null, 'America/Los_Angeles', now()),
  ('Hornitos Ghost Town', 'hornitos-ghost-town', 'weird-history', 37.50299, -120.23824, 'Hornitos', 'CA', 'Stone ruins, an old plaza and surviving historic buildings remain in this isolated former mining town in the Sierra foothills.', 'roadside', 'https://www.yosemite.com/', null, 'America/Los_Angeles', now()),
  ('Iron Door Saloon', 'iron-door-saloon', 'weird-history', 37.83878, -120.23016, 'Groveland', 'CA', 'This long-running Sierra bar occupies an 1850s-era building and leans heavily into its Gold Rush saloon identity, including stories of miners and frontier-era customers.', 'open', 'https://www.iron-door-saloon.com/', null, 'America/Los_Angeles', now()),
  ('North Star Powerhouse Mining Museum', 'north-star-powerhouse-mining-museum', 'weird-history', 39.20225, -121.05877, 'Grass Valley', 'CA', 'A preserved powerhouse and enormous Pelton wheel interpret the machinery that drove deep hard-rock mining in the Grass Valley district.', 'limited', 'https://www.nevadacountyca.gov/', null, 'America/Los_Angeles', now()),
  ('Knight Foundry', 'knight-foundry', 'weird-history', 38.39333, -120.78333, 'Sutter Creek', 'CA', 'One of the country''s rare surviving water-powered foundries retains belt-driven machine tools and nineteenth-century industrial equipment in working context.', 'limited', 'https://knightfoundry.com/', null, 'America/Los_Angeles', now()),
  ('Indian Grinding Rock State Historic Park', 'indian-grinding-rock-state-historic-park', 'weird-history', 38.42489, -120.64352, 'Pine Grove', 'CA', 'Chaw''se preserves an extraordinary limestone outcrop containing more than a thousand bedrock mortar holes, alongside a museum interpreting Miwok culture. Treat the site respectfully.', 'open', 'https://www.parks.ca.gov/?page_id=553', null, 'America/Los_Angeles', now()),
  ('North Bloomfield Ghost Town', 'north-bloomfield-ghost-town', 'weird-history', 39.36823, -120.89939, 'North Bloomfield', 'CA', 'Historic buildings from a hydraulic-mining town survive within Malakoff Diggins State Historic Park, separated from the enormous diggings by trails and old roads.', 'limited', 'https://www.parks.ca.gov/?page_id=494', null, 'America/Los_Angeles', now()),
  ('Locke Historic District', 'locke-historic-district', 'weird-history', 38.25056, -121.50972, 'Locke', 'CA', 'Founded by Chinese immigrants in 1915, Locke preserves the dense wooden streetscape of a rare rural Chinese-American town in the Sacramento-San Joaquin Delta.', 'open', 'https://locke-foundation.org/', null, 'America/Los_Angeles', now()),
  ('Bodie State Historic Park', 'bodie-state-historic-park', 'weird-history', 38.21547, -119.01098, 'Bodie', 'CA', 'Hundreds of structures survive in a state of ''arrested decay'' at one of America''s best-preserved mining ghost towns; winter road access can be difficult or impossible.', 'limited', 'https://www.parks.ca.gov/?page_id=509', null, 'America/Los_Angeles', now()),
  ('Bennettville Ghost Town', 'bennettville-ghost-town', 'weird-history', 37.94366, -119.2362, 'Lee Vining', 'CA', 'A handful of restored mining-camp buildings survive near Tioga Pass, reached by a short high-elevation hike when seasonal roads are open.', 'limited', 'https://www.fs.usda.gov/r05/inyo/recreation', null, 'America/Los_Angeles', now()),
  ('Mono Lake South Tufa Area', 'mono-lake-south-tufa-area', 'roadside-oddities', 37.93852, -119.0266, 'Lee Vining', 'CA', 'Exposed calcium-carbonate tufa towers rise from Mono Lake''s shoreline, remnants of underwater springs revealed as the lake level fell.', 'open', 'https://www.monolake.org/visit/south-tufa/', null, 'America/Los_Angeles', now()),
  ('Hot Creek Geological Site', 'hot-creek-geological-site', 'roadside-oddities', 37.66111, -118.8275, 'Mammoth Lakes', 'CA', 'Scalding springs and shifting blue pools emerge beside an icy Sierra stream; the water is dangerously hot and swimming is prohibited.', 'limited', 'https://www.fs.usda.gov/r05/inyo/recreation', null, 'America/Los_Angeles', now()),
  ('Devils Postpile National Monument', 'devils-postpile-national-monument', 'roadside-oddities', 37.62494, -119.08484, 'Mammoth Lakes', 'CA', 'Columns of cooled basalt form an immense geometric cliff, with a polished top exposing the polygonal structure like a stone honeycomb.', 'limited', 'https://www.nps.gov/depo/', null, 'America/Los_Angeles', now()),
  ('Mammoth Earthquake Fault', 'mammoth-earthquake-fault', 'roadside-oddities', 37.65224, -119.0181, 'Mammoth Lakes', 'CA', 'A deep fissure in volcanic rock near Mammoth Mountain is commonly called an earthquake fault, though geologists interpret it as a tension crack related to volcanic activity.', 'limited', 'https://www.fs.usda.gov/r05/inyo/recreation', null, 'America/Los_Angeles', now()),
  ('Inyo Craters', 'inyo-craters', 'roadside-oddities', 37.68797, -119.00578, 'Mammoth Lakes', 'CA', 'Two water-filled explosion craters mark a relatively recent volcanic event along the Mono-Inyo chain and are reached by a short forest trail.', 'limited', 'https://www.fs.usda.gov/r05/inyo/recreation', null, 'America/Los_Angeles', now()),
  ('Crowley Lake Columns', 'crowley-lake-columns', 'roadside-oddities', 37.60969, -118.72022, 'Crowley Lake', 'CA', 'Thousands of naturally formed stone columns line portions of the reservoir shore, exposed by erosion and best reached only with suitable road and lake conditions.', 'limited', 'https://www.monocounty.org/', null, 'America/Los_Angeles', now()),
  ('Fossil Falls', 'fossil-falls', 'roadside-oddities', 35.9692, -117.91038, 'Little Lake', 'CA', 'Ancient lava was polished and sculpted by glacial-era Owens River water into smooth black chutes and potholes that now sit completely dry.', 'open', 'https://www.blm.gov/visit/fossil-falls', null, 'America/Los_Angeles', now()),
  ('Manzanar National Historic Site', 'manzanar-national-historic-site', 'weird-history', 36.7256, -118.155, 'Independence', 'CA', 'The preserved camp landscape and reconstructed buildings document the incarceration of Japanese Americans during World War II. It is a memorial and history site, not a paranormal attraction.', 'open', 'https://www.nps.gov/manz/', null, 'America/Los_Angeles', now()),
  ('Laws Railroad Museum & Historic Site', 'laws-railroad-museum-historic-site', 'museums', 37.39869, -118.34599, 'Bishop', 'CA', 'A preserved railroad depot, locomotives and relocated historic buildings form a sprawling outdoor museum of Owens Valley transportation and settlement.', 'limited', 'https://www.lawsmuseum.org/', null, 'America/Los_Angeles', now()),
  ('Museum of Western Film History', 'museum-of-western-film-history', 'weird-history', 36.60087, -118.06169, 'Lone Pine', 'CA', 'Costumes, vehicles, props and memorabilia trace the hundreds of productions filmed in the Alabama Hills and surrounding Eastern Sierra.', 'open', 'https://museumofwesternfilmhistory.org/', null, 'America/Los_Angeles', now()),
  ('Mobius Arch', 'mobius-arch', 'roadside-oddities', 36.6136, -118.12573, 'Lone Pine', 'CA', 'A naturally weathered granite arch frames Mount Whitney and the Sierra, reached on a short loop through the bizarre boulder landscape of the Alabama Hills.', 'open', 'https://www.blm.gov/visit/alabama-hills', null, 'America/Los_Angeles', now()),
  ('Ancient Bristlecone Pine Forest — Schulman Grove', 'ancient-bristlecone-pine-forest-schulman-grove', 'roadside-oddities', 37.3853, -118.17827, 'Big Pine', 'CA', 'Trails pass some of the oldest known individual trees on Earth, twisted bristlecone pines growing in stark white dolomite high above Owens Valley.', 'limited', 'https://www.fs.usda.gov/r05/inyo/recreation/ancient-bristlecone-pine-forest', null, 'America/Los_Angeles', now()),
  ('Patriarch Grove', 'patriarch-grove', 'roadside-oddities', 37.52762, -118.1982, 'Big Pine', 'CA', 'A rough high-elevation road reaches an even more remote grove of ancient bristlecone pines, including the massive Patriarch Tree.', 'limited', 'https://www.fs.usda.gov/r05/inyo/recreation/ancient-bristlecone-pine-forest', null, 'America/Los_Angeles', now()),
  ('Darwin Ghost Town', 'darwin-ghost-town', 'weird-history', 36.26827, -117.59173, 'Darwin', 'CA', 'This remote mining settlement is still partly inhabited, with ruins and weathered structures mixed among private homes. Stay on public roads and do not enter abandoned-looking buildings.', 'roadside', 'https://www.inyocounty.us/', null, 'America/Los_Angeles', now()),
  ('Panamint City', 'panamint-city', 'weird-history', 36.11688, -117.08183, 'Panamint Springs', 'CA', 'Ruins of a violent 1870s silver camp lie deep in Surprise Canyon and require a strenuous backcountry hike; this is not a drive-up ghost town.', 'limited', 'https://www.blm.gov/', null, 'America/Los_Angeles', now()),
  ('Skidoo Ghost Town', 'skidoo-ghost-town', 'weird-history', 36.43667, -117.15417, 'Death Valley', 'CA', 'Foundations and mining remnants mark a short-lived Death Valley gold town reached by an unpaved road; conditions and closures should be checked before travel.', 'limited', 'https://www.nps.gov/deva/', null, 'America/Los_Angeles', now()),
